  opacity: 0;
  transform: translateY(-100%);
  pointer-events: none;
}

/* ==========================================================================
   Views Hierarchy & Router Container
   ========================================================================== */
.views-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
}

.view {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  display: none;
  opacity: 0;
  transform: scale(0.99);
  transition: opacity 0.28s cubic-bezier(0.2, 0, 0, 1), transform 0.28s cubic-bezier(0.2, 0, 0, 1);
}

.view.active {
  display: block;
  opacity: 1;
  transform: scale(1.0);
}

/* Scrollable View Content Pane */
.view-scroll-pane {
  position: absolute;
  top: 0;
  left: 0;
  width: 1920px;
  height: 1080px;
  overflow-y: scroll;
  overflow-x: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: smooth;
  padding-top: var(--header-height);
  padding-bottom: 72px;
}

.view-scroll-pane::-webkit-scrollbar {
